import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Glossary","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","frontmatter":{"title":"Glossary","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/glossary.html"}]],"sort":1000},"headers":[],"relativePath":"en/synceta/glossary.md","filePath":"en/synceta/glossary.md","lastUpdated":1785230622000}`),a={name:`en/synceta/glossary.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<p>The glossary for SyncETA is as follows.</p><ul><li><strong>Collection</strong>: A feature that selects multiple scenarios and executes them sequentially. It allows you to flexibly combine various scenarios to meet user needs, ensuring a consistent workflow. If you want to run a single scenario across multiple browsers, you can run it as a collection.</li><li><strong>CI/CD (Continuous Integration/Continuous Deployment)</strong>: Supports seamlessly integrating test automation into development and deployment pipelines to improve the efficiency and quality of the entire software development life cycle. It works smoothly with various external tools/systems like Jenkins, Git, Azure, and DevOps. CI/CD integration ensures continuous and stable quality management and contributes to optimizing the development process.</li><li><strong>Data Set</strong>: A feature to input and manage data in a tabular format, supporting the addition, modification, and deletion of variables. You can write directly by calling variable values set in a scenario, or automatically generate mockup data using AI and conduct tests with various values.</li><li><strong>LLM (Large Language Model)</strong>: A technology utilized to convert recorded user action scenarios into natural language-based test cases. SyncETA uses open-source LLMs like 7B or Mistral and continuously improves the quality of test case generation by the LLM by incorporating QA feedback.</li><li><strong>Playwright MCP</strong>: A technology used in SyncETA&#39;s automated test execution module that generates auto-execution scripts based on test cases approved by QA and supports parallel test execution in a multi-browser automation environment. It provides compatibility with various browsers like Chrome, Firefox, and Edge, and the addition of the Safari browser has also been requested.</li><li><strong>QA (Quality Assurance)</strong>: Performs tasks to guarantee quality and maximize efficiency in the software development process. SyncETA helps all users, including QA engineers, easily build test automation and provides features to directly review and edit generated Excel test cases. QA&#39;s feedback is reflected in LLM learning, contributing to the improvement of test case generation quality.</li><li><strong>QA Feedback Loop</strong>: When a QA engineer reviews and edits generated Excel test cases, this modified data is uploaded to the SyncETA system and utilized as training data for the LLM. Through this, the quality of test case generation is continuously improved, and the reliability and test coverage of auto-generated test cases increase over time.</li><li><strong>Record</strong>: The basic unit for recording user events and DOM information. It captures and records actual user actions within the web browser, such as clicking, typing, scrolling, and page transitions, in real-time along with information like URL, XPath, Class, ID, and Tab information.</li><li><strong>Regression Test Automation</strong>: An automated system and method to reduce the burden of repetitive testing due to shortened development cycles and to continuously manage software quality. Through this, SyncETA provides the effect of shortening the development cycle and accelerating the time-to-market with fast feedback.</li><li><strong>Scenario</strong>: A core component that implements test scenarios by systematically integrating record information. It executes user-defined events in a specified order and enables tracking of execution results through accuracy, stability, and real-time status information via automatic and AI-based verification.</li><li><strong>Selenium</strong>: A technology used in the SyncETA Recorder (User Action Recording Module) that captures users&#39; web browser actions in real-time and automatically generates and saves them as test scenarios in a JSON/YAML-based format. It is a powerful and easy-to-use framework for web automation and testing.</li><li><strong>Story</strong>: One of SyncETA&#39;s important features that allows you to freely connect scenarios through a Flow Chart interface and dynamically execute the next scenario based on verification results. It ensures stability and efficiency with a visual workflow and automatic verification.</li><li><strong>SyncETA</strong>: A web browser action recording and automated test execution system and method through AI-based natural language test case generation. It is an innovative test automation solution that combines Selenium-based browser action recording and AI-based test case generation, aiming to maximize QA work efficiency and software quality. It is an abbreviation for End to end test automation and can be deployed as a Docker-based on-premise installation or a Cloud SaaS format.</li><li><strong>SyncETA Recorder</strong>: Uses Selenium technology to record real-time actions (clicking, typing, scrolling, page movement, tab information, etc.) of an actual user in the browser, logging events and DOM information. The recorded actions are saved as a test scenario in a JSON/YAML-based format.</li><li><strong>Test Executor</strong>: Generates auto-execution scripts based on Excel test cases generated through the TestCase Generator and verified by QA, and executes tests in an actual browser automation environment. It utilizes Playwright MCP and supports parallel test execution and cross-browser compatibility.</li><li><strong>TestCase Generator (Natural Language Test Case Auto-Generation Module)</strong>: A module that receives JSON-format test scenarios generated in the SyncETA Recorder, which the LLM analyzes to automatically generate human-readable, natural language-based Excel test cases. It generates test cases including Step, Input, Expected Result, etc., and can be provided in the form of reusable templates.</li><li><strong>Test Case</strong>: A test scenario document automatically generated based on natural language (mainly in Excel format) through AI (LLM) in the SyncETA system. It includes fields such as Step, Input, Expected Result, and can be verified and modified by a QA engineer.</li><li><strong>Cross-browser Compatibility</strong>: A feature that supports simultaneous testing on multiple browsers from a single PC, supporting compatibility with various browsers like Chrome, Firefox, and Edge.</li><li><strong>No-code/Low-code Test Automation</strong>: SyncETA&#39;s strength that allows even users lacking development knowledge to easily build test automation using an intuitive GUI and keyword-based non-code methods. It increases accessibility for non-technical users (QA teams) by solving the problem of requiring existing development knowledge.</li><li><strong>Error Identification &amp; Diagnosis</strong>: A feature that facilitates error analysis by providing user-friendly error messages, recording screenshots, and providing a recording screen (video) at the time of the error when an error occurs during test execution.</li><li><strong>Dashboard/Management System</strong>: Provides an interface for system monitoring such as scenario registration status, execution status, and error status. It helps with error analysis by allowing video checks in the execution history and providing screenshots and recording screens of error records.</li></ul>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};